package net.kdt.pojavlaunch.fragments;

import android.os.Bundle;import android.view.View;import android.widget.LinearLayout;import android.widget.ProgressBar;import android.widget.TextView;import android.widget.Toast;import androidx.annotation.NonNull;import androidx.annotation.Nullable;import androidx.fragment.app.Fragment;
import net.kdt.pojavlaunch.R;import net.kdt.pojavlaunch.Tools;import net.kdt.pojavlaunch.UiMotion;import net.kdt.pojavlaunch.csclient.*;import java.util.ArrayList;

public class CsClientBuilderFragment extends Fragment{
 public static final String TAG="CS_CLIENT_BUILDER";private CsClientCatalog.VersionEntry version;private LinearLayout chips;private TextView create,status;private ProgressBar progress;
 public CsClientBuilderFragment(){super(R.layout.fragment_cs_client_builder);}
 @Override public void onCreate(@Nullable Bundle s){super.onCreate(s);version=(CsClientCatalog.VersionEntry)requireArguments().getSerializable("version");}
 @Override public void onViewCreated(@NonNull View r,@Nullable Bundle s){chips=r.findViewById(R.id.csc_selection_chips);create=r.findViewById(R.id.csc_create_profile);status=r.findViewById(R.id.csc_install_status);progress=r.findViewById(R.id.csc_install_progress);((TextView)r.findViewById(R.id.csc_builder_eyebrow)).setText("CS CLIENT • MINECRAFT "+version.minecraft);((TextView)r.findViewById(R.id.csc_builder_core)).setText("Blaze "+version.build+" + Fabric Loader + Fabric API");r.findViewById(R.id.csc_builder_back).setOnClickListener(v->requireActivity().getSupportFragmentManager().popBackStack());r.findViewById(R.id.csc_browse_mods).setOnClickListener(v->openPicker(false));r.findViewById(R.id.csc_browse_pack).setOnClickListener(v->openPicker(true));create.setOnClickListener(v->install());UiMotion.pressFeedback(r.findViewById(R.id.csc_builder_back),r.findViewById(R.id.csc_browse_mods),r.findViewById(R.id.csc_browse_pack),create);refresh();}
 @Override public void onResume(){super.onResume();if(chips!=null)refresh();}
 private void openPicker(boolean pack){Bundle b=new Bundle();b.putString("mc",version.minecraft);b.putBoolean("pack",pack);Tools.swapFragment(requireActivity(),CsClientPickerFragment.class,CsClientPickerFragment.TAG,b);}
 private void refresh(){chips.removeAllViews();addChip("✓ Fabric API  •  always included",null);if(CsClientSelection.modpack!=null)addChip("MODPACK  •  "+CsClientSelection.modpack.title,()->{CsClientSelection.modpack=null;refresh();});for(CsClientCatalog.ProjectEntry e:new ArrayList<>(CsClientSelection.mods))addChip("MOD  •  "+e.title,()->{CsClientSelection.toggleMod(e);refresh();});}
 private void addChip(String text,@Nullable Runnable remove){TextView v=new TextView(requireContext());v.setText(text+(remove==null?"":"     ×"));v.setTextColor(0xFFFFFFFF);v.setTextSize(10);v.setGravity(android.view.Gravity.CENTER_VERTICAL);v.setPadding(dp(13),0,dp(13),0);v.setBackgroundResource(R.drawable.bg_cs_client_transparent);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(40));lp.bottomMargin=dp(7);v.setLayoutParams(lp);if(remove!=null)v.setOnClickListener(x->remove.run());chips.addView(v);}
 private void install(){create.setEnabled(false);progress.setVisibility(View.VISIBLE);progress.setIndeterminate(true);CsClientInstaller.install(requireContext(),version,new ArrayList<>(CsClientSelection.mods),CsClientSelection.modpack,new CsClientInstaller.Callback(){public void onStatus(String s){status.setText(s);}public void onDone(boolean ok,String msg){if(!isAdded())return;progress.setVisibility(View.GONE);create.setEnabled(true);Toast.makeText(requireContext(),msg,Toast.LENGTH_LONG).show();if(ok){CsClientSelection.clear();Tools.backToMainMenu(requireActivity());}}});}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
}